*:not(#sk-never) {
    background-color: black !important;
}

section:not(#sk-never), article:not(#sk-never), main:not(#sk-never),
aside:not(#sk-never), nav:not(#sk-never), header:not(#sk-never),
footer:not(#sk-never), form:not(#sk-never), ul:not(#sk-never),
ol:not(#sk-never), table:not(#sk-never), thead:not(#sk-never),
tbody:not(#sk-never), tfoot:not(#sk-never), tr:not(#sk-never) {
    background-color: black !important;
}

table:not(#sk-never), thead:not(#sk-never), tbody:not(#sk-never), tfoot:not(#sk-never),
tr:not(#sk-never), td:not(#sk-never), th:not(#sk-never) {
    background-image: none !important;
}

div:not(#sk-never) {
    background-color: black !important;
}

html:not(#sk-never), body:not(#sk-never) {
    background-color: black !important;
    background-image: none !important;
}

p:not(#sk-never), span:not(#sk-never), li:not(#sk-never),
td:not(#sk-never), th:not(#sk-never), h1:not(#sk-never),
h2:not(#sk-never), h3:not(#sk-never), h4:not(#sk-never),
h5:not(#sk-never), h6:not(#sk-never), blockquote:not(#sk-never),
dt:not(#sk-never), dd:not(#sk-never), figcaption:not(#sk-never),
label:not(#sk-never) {
    background-color: black !important;
}

*:not(#sk-never),
*:not(#sk-never)::before,
*:not(#sk-never)::after {
    color: yellow !important;
}

section:not(#sk-never), article:not(#sk-never), main:not(#sk-never),
aside:not(#sk-never), nav:not(#sk-never), header:not(#sk-never),
footer:not(#sk-never), form:not(#sk-never), ul:not(#sk-never),
ol:not(#sk-never), table:not(#sk-never), thead:not(#sk-never),
tbody:not(#sk-never), tfoot:not(#sk-never), tr:not(#sk-never) {
    color: yellow !important;
}

div:not(#sk-never) {
    color: yellow !important;
}

html:not(#sk-never), body:not(#sk-never) {
    color: yellow !important;
}

p:not(#sk-never), span:not(#sk-never), li:not(#sk-never),
td:not(#sk-never), th:not(#sk-never), h1:not(#sk-never),
h2:not(#sk-never), h3:not(#sk-never), h4:not(#sk-never),
h5:not(#sk-never), h6:not(#sk-never), blockquote:not(#sk-never),
dt:not(#sk-never), dd:not(#sk-never), figcaption:not(#sk-never),
label:not(#sk-never) {
    color: yellow !important;
}

*, *::before, *::after {
    line-height: 1em !important;
}

html, body, div, section,
article, main, aside, nav,
header, footer, form, ul,
ol, table, thead, tbody,
tfoot, tr, p, span,
li, td, th, h1,
h2, h3, h4, h5,
h6, blockquote, dt, dd,
figcaption, label {
    line-height: 1em !important;
}

/* icons, controls and media keep their own metrics */
i, svg, use, symbol,
[class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i],
.fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"],
[class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"],
[aria-hidden="true"], button, input, select,
textarea, option, optgroup, progress,
meter, summary, [role="button"], [role="tab"],
[role="menuitem"], [role="switch"], [role="checkbox"], [role="radio"],
img, picture, video, canvas,
object, embed, iframe, i::before,
i::after, [class*="icon" i]::before, [class*="icon" i]::after, [class*="fa-"]::before,
[class*="fa-"]::after, [class*="material-icons"]::before, [class*="material-symbols"]::before, [class*="octicon"]::before,
[class*="bi-"]::before {
    line-height: normal !important;
}

*:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]),
*:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"])::before,
*:not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"])::after {
    font-family: Arial, Helvetica, sans-serif !important;
}

/* Code keeps a monospace face and a colour that is not body-yellow. #sk-never is an id
   that matches nothing; it exists purely to put these rules on the same specificity
   ladder as the bg/fg blankets, which would otherwise repaint the code yellow. */
pre:not(#sk-never), code:not(#sk-never), kbd:not(#sk-never), samp:not(#sk-never), tt:not(#sk-never) {
    font-family: "DejaVu Sans Mono", "Liberation Mono", Consolas, monospace !important;
    color: #e0e0e0 !important;
}

pre:not(#sk-never) :not(#sk-never), code:not(#sk-never) :not(#sk-never) {
    font-family: "DejaVu Sans Mono", "Liberation Mono", Consolas, monospace !important;
    color: inherit !important;
}

p, span, li, td,
th, h1, h2, h3,
h4, h5, h6, blockquote,
dt, dd, figcaption, label {
    text-align: left !important;
}

*:not(#sk-never),
*:not(#sk-never)::before,
*:not(#sk-never)::after {
    border-color: #ffff00 !important;
    outline-color: #ffff00 !important;
    column-rule-color: #ffff00 !important;
    caret-color: #ffff00 !important;
}

hr:not(#sk-never) {
    border-color: #ffff00 !important;
    background-color: #ffff00 !important;
    color: #ffff00 !important;
}

/* buttons and selects: black ground, yellow trace, pill */
button:not(#sk-never), select:not(#sk-never),
[role="button"]:not(#sk-never), [role="tab"]:not(#sk-never),
[role="switch"]:not(#sk-never), input[type="submit"]:not(#sk-never),
input[type="button"]:not(#sk-never), input[type="reset"]:not(#sk-never) {
    background-color: #000000 !important;
    background-image: none !important;
    color: #ffff00 !important;
    outline: 1px solid #ffff00 !important;
    outline-offset: -1px !important;
    border-radius: 999px !important;
}

/* the same treatment for links that act as buttons */
a[href^="javascript:" i]:not(#sk-never):not(#sk-never),
a[class*="btn" i]:not(#sk-never):not(#sk-never),
a[class*="button" i]:not(#sk-never):not(#sk-never) {
    background-color: #000000 !important;
    background-image: none !important;
    color: #ffff00 !important;
    outline: 1px solid #ffff00 !important;
    outline-offset: -1px !important;
    border-radius: 999px !important;
    padding: 0.25em 0.9em !important;
}

/* single-line text entry: a yellow pill, traced rather than filled. The outline
   follows border-radius, and being an outline it adds no layout of its own — only
   the padding does, which the rounded ends need so text is not clipped. */
input:not(#sk-never):is([type=text], [type=search], [type=email], [type=url], [type=tel],
  [type=password], [type=number], [type=date], [type=datetime-local],
  :not([type])) {
    background-color: #000000 !important;
    background-image: none !important;
    color: #ffff00 !important;
    caret-color: #ffff00 !important;
    border: none !important;
    border-radius: 999px !important;
    outline: 1px solid #ffff00 !important;
    outline-offset: -1px !important;
    padding-left: 0.7em !important;
    padding-right: 0.7em !important;
}

input:not(#sk-never)::placeholder {
    color: #999900 !important;
}

/* a textarea is not a pill — it keeps the traced-box treatment */
textarea:not(#sk-never) {
    background-color: #000000 !important;
    background-image: none !important;
    color: #ffff00 !important;
    caret-color: #ffff00 !important;
    outline: 1px solid #ffff00 !important;
    outline-offset: -1px !important;
}

textarea:not(#sk-never)::placeholder {
    color: #999900 !important;
}

input:not(#sk-never):is([type=checkbox], [type=radio]) {
    accent-color: #ffff00 !important;
}

button:not(#sk-never):hover,
[role="button"]:not(#sk-never):hover,
input:not(#sk-never):is([type=submit], [type=button]):hover,
a[href^="javascript:" i]:not(#sk-never):not(#sk-never):hover,
a[class*="btn" i]:not(#sk-never):not(#sk-never):hover,
a[class*="button" i]:not(#sk-never):not(#sk-never):hover {
    background-color: #ffff00 !important;
    color: #000000 !important;
}

img:not(#sk-never), picture:not(#sk-never),
object:not(#sk-never), embed:not(#sk-never) {
    background-color: #808080 !important;
}

*:empty:not(#sk-never):not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]):not(img, picture, video, canvas, object, embed, iframe) {
    background-image: none !important;
}

[class*="overlay" i]:not(#sk-never):not(#sk-never),
[class*="backdrop" i]:not(#sk-never):not(#sk-never),
[class*="scrim" i]:not(#sk-never):not(#sk-never),
span[class*="ripple" i]:not(#sk-never):not(#sk-never) {
    background-color: transparent !important;
}

/* a control's own floating label, and whatever it carries */
:is(input, textarea, select):not(#sk-never) ~ :is(span, label):not(#sk-never),
:is(input, textarea, select):not(#sk-never) ~ :is(span, label):not(#sk-never) *:not(#sk-never) {
    background-color: transparent !important;
}

:focus-visible:not(#sk-never) {
    outline: 2px solid #00ffff !important;
    outline-offset: 0 !important;
}

/* surfaces */
html:not(#sk-never) {
    --background: #000000 !important;
    --card: #000000 !important;
    --popover: #000000 !important;
    --muted: #000000 !important;
    --sidebar: #000000 !important;
}

/* the ink on them */
html:not(#sk-never) {
    --foreground: #ffff00 !important;
    --card-foreground: #ffff00 !important;
    --popover-foreground: #ffff00 !important;
    --sidebar-foreground: #ffff00 !important;
}

/* secondary text keeps a rank of its own rather than flattening to body yellow */
html:not(#sk-never) {
    --muted-foreground: #999900 !important;
}

/* borders, focus rings and the input outline — line colours, not fills */
html:not(#sk-never) {
    --border: #ffff00 !important;
    --input: #ffff00 !important;
    --ring: #ffff00 !important;
    --sidebar-border: #ffff00 !important;
    --sidebar-ring: #ffff00 !important;
}

*:not(#sk-never):not(img, picture, video, canvas, object, embed, iframe):not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]):not(button, input, select, textarea, option, optgroup, progress, meter, summary, [role="button"], [role="tab"], [role="menuitem"], [role="switch"], [role="checkbox"], [role="radio"]):not([style*="width"]) {
    max-width: none !important;
    width: auto !important;
}

/* A flex item pinned by flex-basis ignores width. Restricted to :only-child, which
   is what makes it safe: a lone column growing to fill its row cannot disturb a
   multi-column layout, because there is no second column. unherd.com's article sits
   in a flex row of exactly one child at `flex: 0 0 50%`, beside 960px of nothing. */
*:only-child:not(#sk-never):not(img, picture, video, canvas, object, embed, iframe):not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]):not(button, input, select, textarea, option, optgroup, progress, meter, summary, [role="button"], [role="tab"], [role="menuitem"], [role="switch"], [role="checkbox"], [role="radio"]) {
    flex-grow: 1 !important;
}

/* Releasing every column would leave the text hard against the window edge, so the
   page keeps a gutter. On <body> rather than on the text elements, so it reads as a
   page margin instead of an indent stacking onto whatever padding a card already has. */
body:not(#sk-never) {
    padding-left: 1em !important;
    padding-right: 1em !important;
}

a:any-link:not(#sk-never),
[role="link"]:not(#sk-never),
a:any-link *:not(#sk-never):not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]),
[role="link"] *:not(#sk-never):not(i, svg, use, symbol, [class*="icon" i], [class*="glyph" i], [class*="symbol" i], [class*="ico-" i], .fa, [class*="fa-"], [class*="material-icons"], [class*="material-symbols"], [class*="octicon"], [class*="bi-"], [class*="emoji" i], [role="img"], [aria-hidden="true"]) {
    color: #00ffff !important;
}

a:visited:not(#sk-never) {
    color: #ff80ff !important;
}

a:any-link:not(#sk-never):hover, a:any-link:not(#sk-never):hover *:not(#sk-never),
a:any-link:not(#sk-never):focus-visible, a:any-link:not(#sk-never):focus-visible *:not(#sk-never),
[role="link"]:not(#sk-never):hover, [role="link"]:not(#sk-never):hover *:not(#sk-never) {
    color: #000000 !important;
    background-color: #00ffff !important;
}

.col-sm-8:not(#sk-never):not(#sk-never),
.col-lg-6:not(#sk-never):not(#sk-never) {
    flex-grow: 1 !important;
}

/* and the tag column beside it, so the article takes the whole row. Scoped to the
   article row: the same Bootstrap classes carry real content elsewhere on the site. */
.article-body.row > .col-lg-3:not(#sk-never) {
    display: none !important;
}

*, *::before, *::after {
    font-size: 16px !important;
}

html, body, div, section,
article, main, aside, nav,
header, footer, form, ul,
ol, table, thead, tbody,
tfoot, tr, p, span,
li, td, th, h1,
h2, h3, h4, h5,
h6, blockquote, dt, dd,
figcaption, label {
    font-size: 16px !important;
}

#detailItem:not(#sk-never) {
    background-image: none !important;
}

#fixedBottom:not(#sk-never),
.js-cookies-info:not(#sk-never):not(#sk-never),
.fabs-row:not(#sk-never):not(#sk-never) {
    background-color: transparent !important;
}

pre.code-block__code {
    padding: 4px 8px !important;
    margin: 2px 0 !important;
}

html, body, div, section,
article, main, aside, nav,
header, footer, form, ul,
ol, table, thead, tbody,
tfoot, tr, p, span,
li, td, th, h1,
